package com.example.quanlybaotri.shared.security;
import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class ServiceTokenProvider{private final RestClient client;private final String secret;private final Map<String,Cached> cache=new HashMap<>();public ServiceTokenProvider(RestClient.Builder b,@Value("${app.identity-url:http://identity-service:8081}")String base,@Value("${app.service-client.secret}")String secret){client=b.baseUrl(base).build();this.secret=secret;}public synchronized String token(String audience){Instant now=Instant.now();Cached c=cache.get(audience);if(c!=null&&c.expiresAt.isAfter(now.plusSeconds(30)))return c.value;TokenResponse r=client.post().uri(u->u.path("/internal/v1/auth/token").queryParam("grant_type","client_credentials").queryParam("audience",audience).build()).headers(h->h.setBasicAuth("inventory-service",secret)).retrieve().body(TokenResponse.class);if(r==null)throw new IllegalStateException("Identity returned no service token");cache.put(audience,new Cached(r.accessToken(),now.plusSeconds(r.expiresIn())));return r.accessToken();}private record Cached(String value,Instant expiresAt){}private record TokenResponse(String accessToken,String tokenType,long expiresIn){}}
